import { NEMORY_UI_LABELS } from './nemory-ui-labels.generated';

/** Same base-language and English fallback as the mobile UI catalog. */
export function nemoryUiLabels(locale?: string | null) {
  const language = locale?.trim().toLowerCase().split(/[-_]/)[0] ?? 'en';
  return Object.hasOwn(NEMORY_UI_LABELS, language)
    ? NEMORY_UI_LABELS[language as keyof typeof NEMORY_UI_LABELS]
    : NEMORY_UI_LABELS.en;
}

/** Shared user-facing capabilities in every supported response mode. */
export function buildNemoryCapabilitiesPrompt(
  plannerCreation = false,
  reminderRecurrence = false,
  uiLocale?: string | null,
  plannerCreationVersion?: number,
): string {
  const l = nemoryUiLabels(uiLocale);
  if (plannerCreation && plannerCreationVersion === 2) return `APP CAPABILITIES
Exact UI labels. Relevant planner/entry suggestions:no pressure/duplicates.
Card→${l.addEntry}(prelinked);editor→${l.linkTo};1link/entry,many entries/item;mention≠link/done.
Community:read-only/public drafts,protect privacy;no invented topics/publishing/replies/expertise.
Resume anytime:bottom⋯→${l.conversations};${l.settings}→${l.help}.
Commitments:current list/triggers;advice≠promise,expiry≠fulfilled;once→executed,ongoing→canceled/replaced/ended;non-alerts need interaction.
Create:current request/acceptance only;quotes/advice/hypotheticals/history≠consent;app confirms. Other actions:manual guidance only,no replacements.
${PLANNER_CAPABILITIES_V2}
Reminder:date09:00;time→next.
Manual:${l.planner}→type→⋯→${l.edit}/${l.delete}/${l.archive};habit archive:${l.finishHabit};reminder:${l.cancelReminder}(retain history,stop alerts).
Repeats:${l.single}(default)/${l.following}/${l.series};explain requested scope→confirm. Complete:task/goal/checklist card/checkbox;habit:expand→date/amount→${l.mark};others:none.
Planner:all,note/checklist exclusive. ${l.calendar}/${l.today}:dates/visibility;future≠today.`;
  return `APP CAPABILITIES
Exact UI labels supersede history.
Suggest one,no pressure/duplicates: goal/stages,habit(day/week,min/max),task,event,reminder,checklist,note.
Card→${l.addEntry}(prelinked);else editor→${l.linkTo};1link/entry,many entries/item;mention≠link/completion.
Community:read-only or privacy-safe public drafts;no invented topics,publish/reply/expertise promises.
Resume anytime:bottom⋯→${l.conversations}; ${l.settings}→${l.help}.
Commitments=current list;honor changes/triggers;advice≠promise,expiry≠fulfillment. End:once executed;ongoing canceled/replaced/ended. Non-alerts need interaction.
Reminders:${reminderRecurrence === true ? 'create once/repeats(step1),days,end date/count' : 'create once; repeats manual'};local timezone,date-only09:00,time-only next. Quotes/advice/hypotheticals/history≠consent;app confirms.
Planners:only create on request/acceptance;say creating;no replacements;explain inability/manual steps.
Manual:${l.planner}→type→⋯→${l.edit}/${l.delete}/${l.archive};habit archive:${l.finishHabit};upcoming reminder:${l.cancelReminder}(keep history,stop alerts).
Repeat actions:MUST explain requested scope ${l.single}(default)/${l.following}/${l.series}→confirm. Completion:task/goal/checklist card,items/stages checkbox;habit:expand→date/amount→${l.mark};others:none.
${plannerCreation === true && plannerCreationVersion === 2 ? PLANNER_CAPABILITIES_V2 : plannerCreation === true ? 'Clarify missing goal/stage dates,event date,habit period+target,checklist items,note content;no copied deadlines/invented dates/links.' : 'Other planners:manual save only; never offer/claim automatic creation/modification/linking, despite history.'}
All there;checklist/note exclusive. ${l.calendar}/${l.today} by date; future≠today.`;
}

const PLANNER_CAPABILITIES_V2 = 'Fields:task/event/reminder dates/times,repeats(day/week/month/year,step1,days,end date/count≠deadline,no overlap);task undated/one alert;event location/important/multiple alerts;goal dates+dated stages+alerts;habit check/count(integer)/value,min/max,unit,day/week norm,days/windows/alerts/end;checklist ordered items;note formatting/pin/available audio;all color/icon. Preserve settings;clarify essentials/conflicts/unsupported,not defaults;never invent dates/links/media.';
